/* Entering view: a fixed 200px of scroll (not a % of the element, so tall boxes in the first
   screen still finish), shifted 40px per stagger step. The original runs these as 500–600ms
   one-shot tweens; scroll-linked is the closest CSS-only match. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .ouraring-reveal {
      animation: ouraring-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--ouraring-reveal-step, 0) * 40px) entry calc(200px + var(--ouraring-reveal-step, 0) * 40px);
    }
    .ouraring-reveal-fade {
      animation-name: ouraring-reveal-fade;
    }
    .ouraring-reveal-blur {
      animation-name: ouraring-reveal-blur;
      animation-range: entry calc(var(--ouraring-reveal-step, 0) * 40px) entry calc(320px + var(--ouraring-reveal-step, 0) * 40px);
    }
  }
}

@keyframes ouraring-reveal-rise {
  from {
    opacity: 0;
    translate: 0 20px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes ouraring-reveal-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes ouraring-reveal-blur {
  from {
    opacity: 0;
    filter: blur(16px);
  }
  to {
    opacity: 1;
    filter: blur(0);
  }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./ouraring-reveal.css";

export interface OuraringRevealProps {
  children: ReactNode;
  /** rise: fade + 20px lift (text) · fade: opacity only · blur: blurred to sharp (pictures) */
  kind?: "rise" | "fade" | "blur";
  /** stagger position: each step starts 40px of scroll later */
  step?: number;
  /** the element to render */
  as?: "div" | "li" | "p";
  className?: string;
}

export function OuraringReveal({ children, kind = "rise", step = 0, as: Tag = "div", className }: OuraringRevealProps) {
  const style = { "--ouraring-reveal-step": step } as CSSProperties;
  return (
    <Tag className={cn("ouraring-reveal", `ouraring-reveal-${kind}`, className)} style={style}>
      {children}
    </Tag>
  );
}
